INSERT INTO tip_tbl (board_no, member_id)
SELECT #{boardNo}, #{memberId}
WHERE NOT EXISTS (
    SELECT 1 FROM tip_tbl WHERE board_no = #{boardNo} AND member_id = #{memberId}
)

mapper.update:
UPDATE member_point_tbl
SET TOTAL_POINT = TOTAL_POINT + 5
WHERE MEMBER_ID = #{memberId}

mapper.select:
select r.report_no, r.target_no, r.target_type, r.member_id, r.report_category, r.report_content, r.report_date, r.report_status, case when r.target_type = 'board' then b.board_title when r.target_type = 'comment' then c.board_comment_content end as targetTitle, case when r.target_type = 'board' then b.writer_id when r.target_type = 'comment' then c.board_comment_writer end as targetId, case when r.target_type = 'board' then r.target_no when r.target_type = 'comment' then c.board_no end as boardNo, (select count(*) from report_tbl where target_no = r.target_no and target_type = r.target_type) as reportCount from report_tbl r inner join ( select target_no, target_type, min(report_no) as first_report_no from report_tbl group by target_no, target_type ) g on r.report_no = g.first_report_no left join board_tbl b on r.target_no = b.board_no and r.target_type = 'board' left join board_comment_tbl c on r.target_no = c.board_comment_no and r.target_type = 'comment'
and r.target_type = #{type}
and r.report_category = #{category}
and r.report_status = #{status}
order by reportCount ${sortOrder}, r.report_status asc
order by r.report_status asc, r.report_date ${sortOrder}
